#include <bits/stdc++.h>
using namespace std;

int main() {
    string p, a;
    getline(cin, p);
    getline(cin, a);

    if (a.size() != p.size()) {
        cout << 'N' << endl;
        return 0;
    }

    int cntP[26] = {0}, cntA[26] = {0};
    for (char c : p) cntP[c - 'a']++;
    for (char c : a) {
        if (c == '*') continue;
        cntA[c - 'a']++;
    }

    bool ok = true;
    for (int i = 0; i < 26; i++) {
        if (cntA[i] > cntP[i]) { ok = false; break; }
    }

    cout << (ok ? 'S' : 'N') << endl;
    return 0;
}
